#| tbl-cap: "Mean bill length (mm) by penguin species."
penguins |>
  dplyr::group_by(species) |>
  dplyr::summarise(mean_bill = mean(bill_length_mm, na.rm = TRUE)) |>
  gt::gt() |>
  gt::opt_stylize(style = 4)
```
